{
  "schemaVersion": 1,
  "documents": [
    {
      "id": "design",
      "path": "DESIGN.md"
    },
    {
      "id": "language",
      "path": "glossary.md"
    },
    {
      "id": "guidance",
      "path": "AGENTS.md"
    },
    {
      "id": "audit-snapshot",
      "path": "docs/repo-audit.md"
    }
  ],
  "scopes": [
    {
      "id": "maintained-repo",
      "paths": [
        "**"
      ],
      "documentIds": [
        "design",
        "language",
        "guidance"
      ],
      "ruleIds": [
        "public-core",
        "checkout-total",
        "quote",
        "acyclic",
        "completion"
      ]
    },
    {
      "id": "historical-audit",
      "paths": [
        "docs/repo-audit.md"
      ],
      "documentIds": [
        "audit-snapshot"
      ],
      "ruleIds": []
    }
  ],
  "rules": [
    {
      "id": "public-core",
      "path": "DESIGN.md",
      "pointer": "The UI never touches storage.",
      "checkIds": [
        "native"
      ]
    },
    {
      "id": "checkout-total",
      "path": "DESIGN.md",
      "pointer": "The agreed checkout total is 10.",
      "checkIds": [
        "native"
      ]
    },
    {
      "id": "quote",
      "path": "DESIGN.md",
      "pointer": "The approved selected-quantity extension returns `quote() = 12` and `quote(2) = 24` through that public core interface.",
      "checkIds": [
        "native"
      ]
    },
    {
      "id": "acyclic",
      "path": "DESIGN.md",
      "pointer": "Static import and re-export dependencies must be acyclic.",
      "checkIds": [
        "native"
      ]
    },
    {
      "id": "completion",
      "path": "DESIGN.md",
      "pointer": "A change is complete when affected journeys and required checks pass on the final inputs; passing units alone does not establish completion.",
      "checkIds": [
        "native"
      ]
    }
  ],
  "checks": [
    {
      "id": "native",
      "command": {
        "executable": "npm",
        "args": [
          "run",
          "check"
        ],
        "cwd": ".",
        "versionArgs": [
          "--version"
        ]
      },
      "inputScopes": [
        "packages/**",
        "package.json",
        "package-lock.json",
        "tsconfig.json",
        "unit.test.mjs",
        "journey.mjs",
        "boundaries.mjs",
        "AGENTS.md",
        "DESIGN.md",
        "glossary.md",
        ".bstack/project.json",
        ".bstack/bin/bstack-check.mjs",
        "docs/repo-audit.md"
      ]
    }
  ],
  "generators": [],
  "acceptanceSources": [
    {
      "id": "checkout",
      "path": "DESIGN.md",
      "pointer": "The agreed checkout total is 10."
    },
    {
      "id": "quote",
      "path": "DESIGN.md",
      "pointer": "The approved selected-quantity extension returns `quote() = 12` and `quote(2) = 24` through that public core interface."
    }
  ]
}

